const bitsPerByte = 8;
const values = 2 ** bitsPerByte;        // 256 distinct patterns
const maxValue = values - 1;            // 0..255
console.log('bits per byte:', bitsPerByte);
console.log('distinct values:', values);
console.log('max value:', maxValue);

// How many bytes to store 70000? Each byte adds 8 bits = 256x range.
function bytesNeeded(n) {
  let bytes = 1;
  while (n > 2 ** (8 * bytes) - 1) bytes++;
  return bytes;
}
console.log('bytes for 70000:', bytesNeeded(70000)); // 3 (16 bits max 65535 is too small)
